/* Client-side search over assets/data/search-index.json (generated by scripts/build.js).
   Powers the live dropdown in every .search box and the full results page (/search). */
(function () {
  var INDEX_URL = '/assets/data/search-index.json';
  var DROPDOWN_LIMIT = 8;
  var PAGE_LIMIT = 300;
  var TYPE_LABEL = { course: 'Course', c: 'Chapter', s: 'Section', u: 'Topic', q: 'Past question' };
  var TYPE_BONUS = { course: 6, c: 4, s: 2, q: 2, u: 1 };

  var indexPromise = null;
  var entries = null;
  var meta = null;

  /* ------------------------------------------------------------ index */

  function normalize(s) {
    return String(s || '')
      .toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9Ͱ-Ͽ]+/g, ' ')
      .trim();
  }

  function load() {
    if (!indexPromise) {
      indexPromise = fetch(INDEX_URL)
        .then(function (r) {
          if (!r.ok) throw new Error('HTTP ' + r.status);
          return r.json();
        })
        .then(prepare)
        .catch(function (err) {
          indexPromise = null;
          throw err;
        });
    }
    return indexPromise;
  }

  function prepare(data) {
    meta = data;
    entries = [];
    data.courses.forEach(function (c) {
      entries.push({
        type: 'course', url: c.url, title: c.code + ' · ' + c.name, snippet: 'Level 4 · Term ' + c.term.split('-')[1],
        term: c.term, code: c.code, set: '', name: c.name,
        nt: normalize(c.code + ' ' + c.name), nm: normalize(c.code.replace(' ', '') + ' ' + c.term), ns: '',
      });
    });
    data.items.forEach(function (row) {
      var doc = data.docs[row[0]];
      var chapter = row[5] >= 0 ? doc.ch[row[5]] : '';
      var src = row[6] || '';
      entries.push({
        type: row[1], url: doc.url + '#' + row[2], title: row[3], snippet: row[4], chapter: chapter, src: src,
        term: doc.term, code: doc.code, set: doc.set, name: doc.name,
        nt: normalize(row[3]),
        nm: normalize(doc.code + ' ' + doc.code.replace(' ', '') + ' set ' + doc.set + ' ' + src),
        ns: normalize(row[4] + ' ' + chapter + ' ' + doc.name),
      });
    });
    return entries;
  }

  /* ----------------------------------------------------------- search */

  function hit(hay, t) {
    if (!hay) return 0;
    if (hay.indexOf(t) === 0 || hay.indexOf(' ' + t) !== -1) return 2;
    return t.length > 1 && hay.indexOf(t) !== -1 ? 1 : 0;
  }

  function score(e, toks, phrase) {
    var s = 0;
    for (var i = 0; i < toks.length; i++) {
      var t = toks[i];
      var h = hit(e.nt, t);
      if (h) { s += h === 2 ? 8 : 5; continue; }
      h = hit(e.nm, t);
      if (h) { s += h === 2 ? 5 : 3; continue; }
      h = hit(e.ns, t);
      if (h) { s += h === 2 ? 2 : 1; continue; }
      // "kmeans" should still find "K-Means": compare with spaces removed.
      if (t.length >= 4) {
        if (e.ct === undefined) e.ct = e.nt.replace(/ /g, '');
        if (e.ct.indexOf(t) !== -1) { s += 5; continue; }
        if (e.ca === undefined) e.ca = (e.nm + e.ns).replace(/ /g, '');
        if (e.ca.indexOf(t) !== -1) { s += 1; continue; }
      }
      return 0;
    }
    if (toks.length > 1 && e.nt.indexOf(phrase) !== -1) s += 10;
    if (e.nt.indexOf(phrase) === 0) s += 3;
    return s + TYPE_BONUS[e.type];
  }

  function search(query, filters, limit) {
    var phrase = normalize(query);
    if (!phrase || !entries) return [];
    var toks = phrase.split(' ');
    var out = [];
    for (var i = 0; i < entries.length; i++) {
      var e = entries[i];
      if (filters) {
        if (filters.term && e.term !== filters.term) continue;
        if (filters.course && e.code !== filters.course) continue;
        if (filters.set && e.set !== filters.set) continue;
      }
      var s = score(e, toks, phrase);
      if (s) out.push({ e: e, s: s, i: i });
    }
    out.sort(function (a, b) { return b.s - a.s || a.i - b.i; });
    return limit ? out.slice(0, limit) : out;
  }

  /* ---------------------------------------------------------- render */

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
    });
  }

  function highlight(text, query) {
    var toks = normalize(query).split(' ').filter(function (t) { return t.length > 1 || /\d/.test(t); });
    if (!toks.length) return esc(text);
    toks.sort(function (a, b) { return b.length - a.length; });
    var re = new RegExp('(' + toks.map(function (t) { return t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }).join('|') + ')', 'gi');
    return String(text).split(re).map(function (part, i) {
      return i % 2 ? '<mark>' + esc(part) + '</mark>' : esc(part);
    }).join('');
  }

  function itemHtml(e, query, id) {
    var bits = ['<span class="sr-type">' + TYPE_LABEL[e.type] + '</span>'];
    if (e.type !== 'course') bits.push('<span>' + esc(e.code) + ' · Set ' + esc(e.set) + '</span>');
    if (e.src) bits.push('<span>' + esc(e.src) + '</span>');
    var sub = e.type === 'q'
      ? [e.chapter, e.snippet].filter(Boolean).join(' · ')
      : (e.type === 'c' || e.type === 'course' ? e.snippet : (e.snippet || e.chapter));
    return '<a class="sr-item" role="option" aria-selected="false"' + (id ? ' id="' + id + '"' : '') + ' href="' + esc(e.url) + '">' +
      '<span class="sr-meta">' + bits.join('') + '</span>' +
      '<span class="sr-title">' + highlight(e.title, query) + '</span>' +
      (sub ? '<span class="sr-snippet">' + highlight(sub, query) + '</span>' : '') +
      '</a>';
  }

  /* --------------------------------------------------------- dropdown */

  var uid = 0;

  function setupBox(box) {
    var form = box.querySelector('.search-form');
    var input = box.querySelector('.search-input');
    var panel = box.querySelector('.search-results');
    if (!form || !input || !panel) return;
    var listId = 'sr-list-' + (++uid);
    panel.id = listId;
    input.setAttribute('aria-controls', listId);
    var selected = -1;

    function options() { return panel.querySelectorAll('.sr-item'); }

    function close() {
      panel.hidden = true;
      input.setAttribute('aria-expanded', 'false');
      input.removeAttribute('aria-activedescendant');
      selected = -1;
    }

    function open() {
      panel.hidden = false;
      input.setAttribute('aria-expanded', 'true');
    }

    function select(i) {
      var opts = options();
      if (!opts.length) return;
      if (selected >= 0 && opts[selected]) opts[selected].setAttribute('aria-selected', 'false');
      selected = (i + opts.length) % opts.length;
      var el = opts[selected];
      el.setAttribute('aria-selected', 'true');
      input.setAttribute('aria-activedescendant', el.id);
      el.scrollIntoView({ block: 'nearest' });
    }

    function render() {
      var q = input.value.trim();
      if (!q) { close(); return; }
      load().then(function () {
        if (input.value.trim() !== q) return;
        var all = search(q, null, 0);
        var top = all.slice(0, DROPDOWN_LIMIT);
        selected = -1;
        if (!top.length) {
          panel.innerHTML = '<span class="sr-empty">No results for “' + esc(q) + '”</span>';
        } else {
          panel.innerHTML = top.map(function (r, i) { return itemHtml(r.e, q, listId + '-' + i); }).join('') +
            '<a class="sr-more" href="/search?q=' + encodeURIComponent(q) + '">See all ' + all.length + ' result' + (all.length === 1 ? '' : 's') + ' →</a>';
        }
        open();
      }, function () {
        panel.innerHTML = '<span class="sr-empty">Search is unavailable right now.</span>';
        open();
      });
    }

    input.addEventListener('focus', function () {
      load().catch(function () {});
      if (input.value.trim()) render();
    });
    input.addEventListener('input', render);
    input.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); if (panel.hidden) render(); else select(selected + 1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); select(selected - 1); }
      else if (e.key === 'Enter') {
        var opts = options();
        if (selected >= 0 && opts[selected]) { e.preventDefault(); opts[selected].click(); }
      } else if (e.key === 'Escape') {
        if (!panel.hidden) close();
        else { input.value = ''; input.blur(); closeMobile(); }
      }
    });
    form.addEventListener('submit', function (e) {
      if (!input.value.trim()) e.preventDefault();
    });
    panel.addEventListener('click', function (e) {
      if (e.target.closest('a')) { close(); closeMobile(); }
    });
    document.addEventListener('click', function (e) {
      if (!box.contains(e.target)) close();
    });
  }

  function closeMobile() {
    var bar = document.querySelector('.site-bar');
    if (bar) bar.classList.remove('search-active');
  }

  /* -------------------------------------------------- keyboard shortcut */

  function visible(el) {
    return !!(el && (el.offsetWidth || el.offsetHeight || el.getClientRects().length));
  }

  function focusSearch() {
    var page = document.querySelector('[data-search-page] input[name="q"]');
    var hero = document.querySelector('.search--hero .search-input');
    var barInput = document.querySelector('.search--bar .search-input');
    var target = page || hero;
    if (!visible(target)) target = null;
    if (!target && barInput) {
      if (!visible(barInput)) {
        var bar = document.querySelector('.site-bar');
        if (bar) bar.classList.add('search-active');
      }
      target = barInput;
    }
    if (target) { target.focus(); target.select(); }
  }

  document.addEventListener('keydown', function (e) {
    var t = e.target;
    var typing = t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
    if ((e.key === 'k' || e.key === 'K') && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      focusSearch();
    } else if (e.key === '/' && !typing && !e.ctrlKey && !e.metaKey && !e.altKey) {
      e.preventDefault();
      focusSearch();
    }
  });

  /* ------------------------------------------------------ results page */

  function setupPage(form) {
    var input = form.querySelector('input[name="q"]');
    var termSel = form.querySelector('select[name="term"]');
    var courseSel = form.querySelector('select[name="course"]');
    var setSel = form.querySelector('select[name="set"]');
    var summary = document.querySelector('.search-summary');
    var results = document.querySelector('.search-page-results');
    var params = new URLSearchParams(location.search);

    input.value = params.get('q') || '';

    function run() {
      var q = input.value.trim();
      var filters = { term: termSel.value, course: courseSel.value, set: setSel.value };
      var next = new URLSearchParams();
      if (q) next.set('q', q);
      if (filters.term) next.set('term', filters.term);
      if (filters.course) next.set('course', filters.course);
      if (filters.set) next.set('set', filters.set);
      var qs = next.toString();
      history.replaceState(null, '', location.pathname + (qs ? '?' + qs : ''));
      document.title = (q ? '“' + q + '” · ' : '') + 'Search · MTE Solution Books';

      if (!q) {
        summary.textContent = 'Type a topic, formula name, course code or exam year.';
        results.innerHTML = '';
        return;
      }
      var found = search(q, filters, 0);
      var shown = found.slice(0, PAGE_LIMIT);
      summary.textContent = found.length
        ? found.length + ' result' + (found.length === 1 ? '' : 's') + ' for “' + q + '”' + (found.length > PAGE_LIMIT ? ' (showing the best ' + PAGE_LIMIT + ')' : '')
        : 'No results for “' + q + '”. Try fewer or different words.';

      var groups = [];
      var byKey = {};
      shown.forEach(function (r) {
        var key = r.e.code;
        if (!byKey[key]) {
          byKey[key] = { code: r.e.code, name: r.e.name, items: [] };
          groups.push(byKey[key]);
        }
        byKey[key].items.push(r.e);
      });
      results.innerHTML = groups.map(function (g) {
        return '<section class="sr-group"><h2>' + esc(g.code) + ' <span>' + esc(g.name) + '</span></h2>' +
          g.items.map(function (e) { return itemHtml(e, q); }).join('') + '</section>';
      }).join('');
    }

    summary.textContent = 'Loading search index…';
    load().then(function () {
      var terms = [];
      meta.courses.forEach(function (c) {
        if (terms.indexOf(c.term) === -1) terms.push(c.term);
        courseSel.insertAdjacentHTML('beforeend', '<option value="' + esc(c.code) + '">' + esc(c.code + ' · ' + c.name) + '</option>');
      });
      terms.forEach(function (t) {
        termSel.insertAdjacentHTML('beforeend', '<option value="' + esc(t) + '">' + esc(t) + '</option>');
      });
      termSel.value = params.get('term') || '';
      courseSel.value = params.get('course') || '';
      setSel.value = params.get('set') || '';
      run();
    }, function () {
      summary.textContent = 'Search is unavailable right now. Please try again later.';
    });

    form.addEventListener('submit', function (e) { e.preventDefault(); run(); });
    input.addEventListener('input', function () { if (entries) run(); });
    [termSel, courseSel, setSel].forEach(function (s) {
      s.addEventListener('change', function () { if (entries) run(); });
    });
  }

  /* ------------------------------------------------------------ init */

  function init() {
    var boxes = document.querySelectorAll('.search');
    for (var i = 0; i < boxes.length; i++) setupBox(boxes[i]);
    var pageForm = document.querySelector('[data-search-page]');
    if (pageForm) setupPage(pageForm);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
